{"explanation":"The tangent function y = tan(x) equals sin(x)/cos(x), so it is undefined wherever cos(x) = 0. Those points are vertical asymptotes: x = π/2 + kπ (odd multiples of π/2). On (−2π, 2π) they sit at −3π/2, −π/2, π/2, and 3π/2. Between consecutive asymptotes tan(x) is continuous and strictly increases from −∞ to +∞, and the whole pattern repeats every π.","manimCode":"const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-4, 4, 1],
  xLength: 11,
  yLength: 5.5,
  tips: true
});
ax.moveTo([0, 0.2, 0]);

const xLabel = new MathTex({ latex: 'x' });
await xLabel.waitForRender();
xLabel.scale(0.7);
xLabel.nextTo(ax, RIGHT);
xLabel.shift(scaleVec(0.3, DOWN));

const yLabel = new MathTex({ latex: 'y' });
await yLabel.waitForRender();
yLabel.scale(0.7);
yLabel.nextTo(ax, UP);
yLabel.shift(scaleVec(0.3, LEFT));

const title = new MathTex({ latex: 'y = \\tan(x)' });
await title.waitForRender();
title.scale(0.85);
title.moveTo([0, 3.5, 0]);

scene.add(ax, xLabel, yLabel, title);

// Branches between asymptotes (open intervals)
const branches = [
  [-2 * Math.PI + 0.05, -3 * Math.PI / 2 - 0.05],
  [-3 * Math.PI / 2 + 0.05, -Math.PI / 2 - 0.05],
  [-Math.PI / 2 + 0.05, Math.PI / 2 - 0.05],
  [Math.PI / 2 + 0.05, 3 * Math.PI / 2 - 0.05],
  [3 * Math.PI / 2 + 0.05, 2 * Math.PI - 0.05]
];

const curves = [];
for (const [a, b] of branches) {
  const c = ax.plot(x => Math.tan(x), {
    color: BLUE,
    xRange: [a, b],
    numSamples: 200
  });
  curves.push(c);
  scene.add(c);
}

// Vertical asymptotes
const asymX = [-3 * Math.PI / 2, -Math.PI / 2, Math.PI / 2, 3 * Math.PI / 2];
const asymLabels = ['-3\\pi/2', '-\\pi/2', '\\pi/2', '3\\pi/2'];
const asymLines = [];

for (let i = 0; i < asymX.length; i++) {
  const x = asymX[i];
  const line = new Line({
    start: ax.c2p(x, -4),
    end: ax.c2p(x, 4),
    color: RED_C
  });
  line.setStrokeWidth(2);
  line.setOpacity(0.7);
  asymLines.push(line);
  scene.add(line);

  const lab = new MathTex({ latex: asymLabels[i] });
  await lab.waitForRender();
  lab.scale(0.45);
  lab.setColor(RED_A);
  const pt = ax.c2p(x, -4);
  lab.moveTo([pt[0], pt[1] - 0.35, 0]);
  scene.add(lab);
}

// Interactive explorer: moving point + value readout
let tVal = 0.8;
const dot = new Dot({ point: ax.c2p(tVal, Math.tan(tVal)), color: YELLOW });
scene.add(dot);

let valueTex = new MathTex({
  latex: `\\tan(${tVal.toFixed(2)}) \\approx ${Math.tan(tVal).toFixed(2)}`
});
await valueTex.waitForRender();
valueTex.scale(0.55);
valueTex.moveTo([0, -3.4, 0]);
scene.add(valueTex);

const note = new Text({
  text: 'Asymptotes where cos(x)=0  (odd multiples of π/2)',
  color: GRAY,
  fontSize: 22
});
note.moveTo([0, -3.85, 0]);
scene.add(note);

function refreshDotAndLabel(v) {
  tVal = v;
  // Keep clear of asymptotes so tan is finite
  const eps = 0.08;
  for (const a of asymX) {
    if (Math.abs(v - a) < eps) {
      v = a + (v >= a ? eps : -eps);
      tVal = v;
      break;
    }
  }
  const y = Math.tan(v);
  const clampedY = Math.max(-3.9, Math.min(3.9, y));
  dot.moveTo(ax.c2p(v, clampedY));

  const pos = valueTex.getCenter();
  scene.remove(valueTex);
  const yStr = Math.abs(y) > 50 ? (y > 0 ? '+\\infty' : '-\\infty') : y.toFixed(2);
  valueTex = new MathTex({
    latex: `\\tan(${v.toFixed(2)}) \\approx ${yStr}`
  });
  valueTex.waitForRender().then(() => {
    valueTex.scale(0.55);
    valueTex.moveTo(pos);
    scene.add(valueTex);
  });
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'x',
  min: -2 * Math.PI + 0.1,
  max: 2 * Math.PI - 0.1,
  value: tVal,
  step: 0.05,
  onChange: (v) => refreshDotAndLabel(v)
});
controls.addButton({
  label: 'Jump near π/2',
  onClick: () => refreshDotAndLabel(Math.PI / 2 - 0.15)
});
controls.addButton({
  label: 'Reset',
  onClick: () => refreshDotAndLabel(0.8)
});

// Hover feedback on asymptotes
for (const line of asymLines) {
  makeHoverable(line, scene, { hoverColor: YELLOW, hoverScale: 1.0 });
}

await scene.wait(999999);"}

